@startuml

class Bus {
  + LicensePlateNumber : string
  + InRepairShop : boolean
}

class Driver {
  + Name : string
  + ID : int
  + OnSickLeave : boolean
}

class Route {
  + RouteNumber : int
}

class Shift {
  + StartTime : datetime
  + EndTime : datetime
}

class Schedule {
  + RouteNumber : int
  + Day : date
  + MorningShift : Shift
  + AfternoonShift : Shift
  + NightShift : Shift
}

class BusOnRoute {
  + Bus : Bus
  + Route : Route
  + Date : date
}

Bus "1" -- "*" BusOnRoute
Driver "1" -- "*" BusOnRoute
Route "1" -- "*" BusOnRoute
Schedule "1" -- "*" BusOnRoute

@enduml

